{
  "task_summary": "Predict whether an ACS person recently changed residence rather than living in the same house as one year ago.",
  "scores": [
    {
      "feature": "AGEP",
      "score": 0.9,
      "rationale": "Age is a consistently strong life-cycle predictor of residential mobility."
    },
    {
      "feature": "SCHL",
      "score": 0.62,
