    {
      "feature": "ESP",
      "score": 0.36,
      "rationale": "Parental employment status is context-dependent and often only applicable to children, limiting stable usefulness."
    },
    {
      "feature": "CIT",
      "score": 0.3,
      "rationale": "Citizenship may correlate with migration history but risks demographic shortcutting and state-specific composition effects."
    },
    {
      "feature": "MIL",
      "score": 0.56,
      "rationale": "Military status has a plausible stable link to relocation, though applicability and coding vary by subgroup."
    },
    {
      "feature": "ANC",
      "score": 0.12,
      "rationale": "Ancestry is a demographic and geography-correlated shortcut with weak causal relevance to current mobility."
    },
    {
      "feature": "NATIVITY",
      "score": 0.24,
      "rationale": "Nativity may capture migration background but is a sensitive demographic proxy with distributional artifacts."
    },
    {
      "feature": "RELP",
      "score": 0.68,
      "rationale": "Household relationship stably reflects life stage and household structure, both relevant to moving."
    },
    {
      "feature": "DEAR",
      "score": 0.28,
      "rationale": "Hearing difficulty may weakly affect mobility constraints but has limited marginal predictive value."
    },
    {
      "feature": "DEYE",
      "score": 0.27,
      "rationale": "Vision difficulty is only weakly and indirectly related to residential mobility."
    },
    {
      "feature": "DREM",
      "score": 0.34,
      "rationale": "Cognitive difficulty may affect independence and moving constraints, but signal is limited and subgroup-specific."
    },
    {
      "feature": "RAC1P",
      "score": 0.1,
      "rationale": "Race is a sensitive demographic shortcut and likely captures state-specific structural and geographic artifacts."
    },
    {
      "feature": "GCL",
      "score": 0.32,
      "rationale": "Grandparent-care status reflects household structure but is sparse and subgroup-specific."
    },
    {
      "feature": "COW",
      "score": 0.5,
      "rationale": "Class of worker relates to job stability and relocation but is less direct and missing for nonworkers."
    },
    {
      "feature": "ESR",
      "score": 0.6,
      "rationale": "Employment status is a stable indicator of labor-market attachment and potential moving pressures."
    },
    {
      "feature": "WKHP",
      "score": 0.46,
      "rationale": "Usual work hours proxy labor attachment but are indirect and unavailable or less meaningful for many people."
    },
    {
      "feature": "JWMNP",
      "score": 0.4,
      "rationale": "Commute time can relate to residential-job mismatch but is brittle, work-only, and locally distribution-dependent."
    },
    {
      "feature": "PINCP",
      "score": 0.58,
      "rationale": "Personal income affects housing options and moving costs, though it also reflects local labor and cost-of-living variation."
    }
  ]
}

